class FakeRoom:
    def __init__(self, tool_delay: float = 0.0, tool_answer: dict[str, Any] | None = None) -> None:
        self.posts: list[tuple[str, dict[str, Any]]] = []
        self.tool_delay = tool_delay
        self.tool_answer = tool_answer

    async def post(self, path: str, body: dict[str, Any], timeout: float = 15.0) -> tuple[int, dict[str, Any]]:
        self.posts.append((path, body))
        if path.endswith("/tool"):
            if self.tool_delay:
                await asyncio.sleep(self.tool_delay)
            if self.tool_answer is not None:
                return 200, self.tool_answer
            if body["name"] == "propose_story":
                return 200, {"ok": False, "code": "invalid_choice"}
            return 200, {"ok": True, "state": {"turn": body["turn_id"]}}
        if path.endswith("/done"):
            return 200, {"state": "answered" if body["ok"] else "failed"}
        return 200, {"logged": True, "played": True}

    def of(self, suffix: str) -> list[dict[str, Any]]:
        return [body for path, body in self.posts if path.endswith(suffix)]


class FakeVoice:
    def __init__(self, delay: float = 0.0) -> None:
        self.delay = delay
        self.calls: list[tuple[str, str]] = []

    async def synth(self, text: str, voice: str) -> tuple[bytes | None, dict[str, Any]]:
        self.calls.append((text, voice))
        if self.delay:
            await asyncio.sleep(self.delay)
        return b"RIFF....WAVE", {"seconds": 1.0, "synth_s": 0.1}


