    path = Path(tempfile.mkdtemp(prefix="v51-", dir="/tmp"))
    yield path
    shutil.rmtree(path, ignore_errors=True)


async def call(path: Path, ticket: str | None, argv: list[str], stdin: str | None = None) -> dict[str, Any]:
    reader, writer = await asyncio.open_unix_connection(str(path))
    writer.write(json.dumps({"ticket": ticket, "argv": argv, "stdin": stdin}, ensure_ascii=False).encode() + b"\n")
    await writer.drain()
    line = await reader.readline()
    writer.close()
    return json.loads(line)


def settings(rundir: Path, **overrides: Any) -> hub.HubSettings:
    values = {"webhook": "http://127.0.0.1:9" + HOOK_PATH, "socket": rundir / "hub.sock", "target": "prod",
              "first_call": 5.0, "timeout": 8.0, **overrides}
    return hub.HubSettings(**values)


async def a_bridge(rundir: Path, room: FakeRoom, **kwargs: Any) -> hub.HubBridge:
    bridge = hub.HubBridge(rundir / "hub.sock", "prod", room, **kwargs)
    await bridge.start()
    return bridge


class Hub:
    """The thread's side: the webhook POST records the payload; `ticket()` waits for it."""

    def __init__(self, answer: tuple[bool, str | None] = (True, None)) -> None:
        self.payloads: list[dict[str, Any]] = []
        self.answer = answer

    def post(self, url: str, payload: dict[str, Any], timeout: float = 15.0) -> tuple[bool, str | None]:
        self.payloads.append(payload)
        return self.answer

    async def ticket(self, index: int = 0) -> str:
        for _ in range(500):
            if len(self.payloads) > index:
                return self.payloads[index]["ticket"]
            await asyncio.sleep(0.01)
        raise AssertionError("no webhook POST")


def run(coroutine):
    return asyncio.run(coroutine)


